<script>
import {data,profile} from '../store.js';
import {requirementAudit,unusedCoursework} from '../degree-audit.js';
import {termLabel} from '../academics.js';
import Icon from './Icon.svelte';
let query=$state('');let filter=$state('All requirements');
let groups=$derived(requirementAudit($profile,$data));
let stages=$derived([...new Set(groups.map(g=>g.stage))]);
let shown=$derived(groups.filter(g=>(filter==='All requirements'||g.status===filter)&&`${g.title} ${g.description} ${g.rows.map(r=>`${r.code} ${r.title}`).join(' ')}`.toLowerCase().replace(/\s/g,'').includes(query.toLowerCase().replace(/\s/g,''))));
let unused=$derived(unusedCoursework($profile));
</script>
<section class="panel padded audit-intro"><div class="section-heading"><div><span class="eyebrow">Computer Science · B.S.</span><h2>My Academic Requirements</h2></div><span class="badge neutral">Catalog {$profile.plan.student.catalogYear}</span></div><p class="muted spaced">Explore each requirement to see the courses, grades, terms, and credits applied toward it.</p><div class="audit-status-summary"><span><Icon name="check" size={15}/>{groups.filter(g=>g.status==='Complete').length} complete</span><span><Icon name="clock" size={15}/>{groups.filter(g=>g.status==='In progress').length} in progress</span><span><Icon name="calendar" size={15}/>{groups.filter(g=>g.status==='Planned').length} planned</span></div><div class="academic-controls"><div class="search-box"><Icon name="search" size={17}/><input type="search" aria-label="Search academic requirements" placeholder="Requirement, course code, or title" bind:value={query}/></div><label>Status<select bind:value={filter}><option>All requirements</option><option>Complete</option><option>In progress</option><option>Planned</option><option>Remaining</option></select></label></div><p class="fine-print">A passing grade completes a course. Current and future courses remain separate from earned credit. TA denotes transfer credit and is excluded from GPA; P denotes a passing grade without GPA points.</p></section>
{#each stages as stage}{@const items=shown.filter(g=>g.stage===stage)}{#if items.length}<section class="audit-stage spaced"><h2>{stage}</h2><div class="audit-requirements">{#each items as group}<details class="panel audit-requirement" open={filter!=='All requirements'||!!query||group.status!=='Complete'}><summary><span><strong>{group.title}</strong><small>{group.earned.toFixed(2)} earned / {group.credits.toFixed(2)} required credits</small></span><span class="badge" class:success={group.status==='Complete'} class:warning={group.status==='In progress'} class:neutral={['Planned','Remaining'].includes(group.status)}>{group.status}</span><Icon name="down" size={16}/></summary><div class="audit-requirement-body"><p>{group.description}</p><div class="table-scroll"><table class="academic-table"><caption class="sr-only">Coursework applied to {group.title}</caption><thead><tr><th>Course</th><th>Description</th><th>Units</th><th>When</th><th>Grade</th><th>Status</th></tr></thead><tbody>{#each group.rows as row}<tr><th scope="row">{row.code}</th><td>{row.title}{#if row.notes}<small>Report note {row.notes}</small>{/if}</td><td>{row.credits.toFixed(2)}</td><td>{termLabel(row.term)}</td><td><strong>{row.grade}</strong></td><td><span class="badge" class:success={row.status==='Complete'} class:warning={row.status==='In progress'} class:neutral={['Planned','Enrolled','Remaining'].includes(row.status)}>{row.status}</span></td></tr>{/each}</tbody></table></div>{#if group.status==='Planned'}<p class="fine-print">Planned coursework is not earned credit. Confirm the course through My Class Schedule.</p><a class="text-link" href="#/academics/graduation-plan">Review graduation plan<Icon name="arrow" size={14}/></a>{/if}</div></details>{/each}</div></section>{/if}{/each}
{#if !shown.length}<section class="panel empty-state spaced"><h2>No matching requirements.</h2><p>Try another course code or status.</p><button class="button secondary spaced" onclick={()=>{query='';filter='All requirements';}}>Clear filters</button></section>{/if}
<section class="panel padded spaced academic-copy"><h2>Courses Not Used by the Audit</h2><p>These credits are recorded in course history but are not applied to the requirement groups above.</p><div class="table-scroll"><table class="academic-table"><thead><tr><th>Course</th><th>Description</th><th>Units not applied</th><th>When</th><th>Grade</th></tr></thead><tbody>{#each unused as row}<tr><th scope="row">{row.code}</th><td>{row.title}</td><td>{row.credits.toFixed(2)}</td><td>{termLabel(row.term)}</td><td>{row.grade}</td></tr>{/each}</tbody></table></div><p class="fine-print">ESL1011 appears in two places because 0.99 credits apply toward Probability and Statistics and 0.01 credits remain unused. Its full 1.00 credit is counted only once in course history.</p></section>
<section class="panel padded spaced academic-copy"><h2>Total College Level Hours</h2><p>The degree requires {$profile.audit.requiredCredits} college-level credit hours. Remedial hours do not count toward this total.</p><dl class="academic-definition"><div><dt>Required by the report</dt><dd>{$profile.audit.requiredCredits.toFixed(2)}</dd></div><div><dt>Hours listed as taken in the report</dt><dd>{$profile.audit.reportedTaken.toFixed(2)}</dd></div><div><dt>Credits not used by the audit</dt><dd>{$profile.audit.reportedUnused.toFixed(2)}</dd></div></dl><p class="fine-print">The report lists 133.01 hours taken. The progress totals above use the course rows available here and keep current and planned credits separate; additional report coursework is not inferred.</p></section>
